{"query":"query simulateTransactions($chainId: Int!, $transactions: [Transaction!]!, $domain: String) {
  simulateTransactions(
    chainID: $chainId
    transactions: $transactions
    domain: $domain
  ) {
    scanning {
      result
      description
    }
    error {
      message
      type
    }
    gas {
      estimate
    }
    simulation {
      in {
        ...change
      }
      out {
        ...change
      }
      approvals {
        asset {
          ...asset
        }
        spender {
          ...target
        }
        quantityAllowed
        quantityAtRisk
        expiration
      }
      meta {
        transferTo {
          ...target
        }
        to {
          ...target
        }
      }
      delegation {
        address
        name
        iconURL
        created
        sourceCodeStatus
      }
    }
  }
}

fragment change on TransactionSimulationChange {
  asset {
    ...asset
  }
  quantity
}

fragment asset on TransactionSimulationAsset {
  assetCode
  decimals
  iconURL
  name
  network
  symbol
  type
  interface
  tokenId
  status
}

fragment target on TransactionSimulationTarget {
  address
  name
  iconURL
  function
